-- private.member_take_window(p_user uuid, p_range tstzrange, p_own_take uuid)
CREATE OR REPLACE FUNCTION private.member_take_window(p_user uuid, p_range tstzrange, p_own_take uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  -- HD-3s-F2-F1 (CGR-289 (a), ADR-230): the one reading «this person is busy in the window of a live take». The window is
  -- the order's whole slot [starts_at, ends_at), so the pause of a split take counts as busy, as on the order path
  -- (order_member_step, step 3: her live take of another overlapping order). Every live take counts, before and after its
  -- start (released_at is null). The take a visit was written from (p_own_take, care_visits.order_take_id) never counts
  -- for that visit, so a take never blocks its own block visits. Returns the earliest such take, or null. Instants, not
  -- days, so a window across midnight is read correctly. Callers take the person lock order_take_member:<user> first.
  select k.id
  from public.order_takes k
  join public.partner_requests q on q.id = k.order_id
  where p_user is not null and p_range is not null and not isempty(p_range)
    and k.member_id = p_user and k.released_at is null
    and tstzrange(q.starts_at, q.ends_at, '[)') && p_range
    and (p_own_take is null
         or k.order_id is distinct from (select t.order_id from public.order_takes t where t.id = p_own_take))
  order by q.starts_at, k.id
  limit 1
$function$;

revoke all on function private.member_take_window(p_user uuid, p_range tstzrange, p_own_take uuid) from public, anon, authenticated, service_role;
comment on function private.member_take_window(p_user uuid, p_range tstzrange, p_own_take uuid) is 'HD-3s-F2-F1 (CGR-289 (a), ADR-230): the earliest live take of the person whose whole order window [starts_at, ends_at), pause included, meets the range; the take a visit was written from never counts for it. Null when none. Internal.';
